/*
 * evo_charset - subtitle text of any encoding, as UTF-8. See evo_charset.h.
 *
 * Tables: evo_charset_tables.inc, generated by tools/gen_charset_tables.py.
 * No iconv here: the app module's libc does not have it.
 */
#include "evo_charset.h"

#include <ctype.h>
#include <stdlib.h>
#include <string.h>

#include "evo_charset_tables.inc"

enum cs {
    CS_UTF8,
    CS_UTF16LE,
    CS_UTF16BE,
    CS_1250,
    CS_1251,
    CS_1252,
    CS_1253,
    CS_1254,
    CS_1255,
    CS_1256,
    CS_1257,
    CS_874,
    CS_GBK,
    CS_BIG5,
    CS_SJIS,
    CS_EUCKR,
    CS_NONE
};

static const char *const cs_names[] = {
    "UTF-8", "UTF-16LE", "UTF-16BE", "windows-1250", "windows-1251", "windows-1252",
    "windows-1253", "windows-1254", "windows-1255", "windows-1256", "windows-1257", "windows-874",
    "GBK", "Big5", "Shift-JIS", "EUC-KR", "none"};

static const unsigned short *const single_tables[] = {
    evo_cs_cp1250, evo_cs_cp1251, evo_cs_cp1252, evo_cs_cp1253, evo_cs_cp1254,
    evo_cs_cp1255, evo_cs_cp1256, evo_cs_cp1257, evo_cs_cp874};

struct dbcs {
    const unsigned short *table;
    int lead_lo, lead_hi, trail_lo, trail_hi;
};

static const struct dbcs dbcs_info[4] = {
    {evo_cs_gbk, 0x81, 0xFE, 0x40, 0xFE},
    {evo_cs_big5, 0x81, 0xFE, 0x40, 0xFE},
    {evo_cs_sjis, 0x81, 0xFC, 0x40, 0xFC},
    {evo_cs_euckr, 0x81, 0xFE, 0x41, 0xFE},
};

static const struct dbcs *dbcs_of(enum cs cs) {
    return &dbcs_info[cs - CS_GBK];
}

static int is_dbcs(enum cs cs) {
    return cs >= CS_GBK && cs <= CS_EUCKR;
}

/* ---- UTF-8 ------------------------------------------------------------- */

static int valid_utf8(const unsigned char *p, size_t n) {
    size_t i = 0;
    while (i < n) {
        unsigned char c = p[i];
        size_t extra;
        if (c < 0x80) {
            ++i;
            continue;
        } else if (c >= 0xC2 && c <= 0xDF) {
            extra = 1;
        } else if (c >= 0xE0 && c <= 0xEF) {
            extra = 2;
        } else if (c >= 0xF0 && c <= 0xF4) {
            extra = 3;
        } else {
            return 0;
        }
        if (i + extra >= n)
            return 0;
        for (size_t k = 1; k <= extra; ++k)
            if ((p[i + k] & 0xC0) != 0x80)
                return 0;
        i += extra + 1;
    }
    return 1;
}

static size_t put_utf8(char *out, unsigned long cp) {
    if (cp < 0x80) {
        out[0] = (char)cp;
        return 1;
    }
    if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        out[0] = (char)(0xE0 | (cp >> 12));
        out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (char)(0xF0 | (cp >> 18));
    out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
}

/* ---- Language hints from the file name --------------------------------- */

static enum cs hint_from_token(const char *t) {
    static const struct {
        const char *token;
        enum cs cs;
    } map[] = {
        {"ru", CS_1251}, {"rus", CS_1251}, {"russian", CS_1251}, {"uk", CS_1251},
        {"ukr", CS_1251}, {"bg", CS_1251}, {"bul", CS_1251}, {"sr", CS_1251},
        {"srp", CS_1251}, {"mk", CS_1251}, {"be", CS_1251},
        {"el", CS_1253}, {"gre", CS_1253}, {"ell", CS_1253}, {"greek", CS_1253},
        {"he", CS_1255}, {"heb", CS_1255}, {"hebrew", CS_1255}, {"iw", CS_1255},
        {"ar", CS_1256}, {"ara", CS_1256}, {"arabic", CS_1256}, {"fa", CS_1256},
        {"fas", CS_1256}, {"per", CS_1256}, {"persian", CS_1256}, {"farsi", CS_1256},
        {"ur", CS_1256}, {"urd", CS_1256},
        {"tr", CS_1254}, {"tur", CS_1254}, {"turkish", CS_1254},
        {"pl", CS_1250}, {"pol", CS_1250}, {"cs", CS_1250}, {"cze", CS_1250},
        {"ces", CS_1250}, {"sk", CS_1250}, {"slo", CS_1250}, {"hu", CS_1250},
        {"hun", CS_1250}, {"ro", CS_1250}, {"rum", CS_1250}, {"ron", CS_1250},
        {"hr", CS_1250}, {"hrv", CS_1250}, {"sl", CS_1250}, {"slv", CS_1250},
        {"lt", CS_1257}, {"lv", CS_1257}, {"et", CS_1257}, {"lit", CS_1257},
        {"lav", CS_1257}, {"est", CS_1257},
        {"th", CS_874}, {"tha", CS_874}, {"thai", CS_874},
        {"zh", CS_GBK}, {"chi", CS_GBK}, {"zho", CS_GBK}, {"chs", CS_GBK},
        {"gb", CS_GBK}, {"gbk", CS_GBK}, {"sc", CS_GBK}, {"zhcn", CS_GBK},
        {"simplified", CS_GBK},
        {"cht", CS_BIG5}, {"big5", CS_BIG5}, {"tc", CS_BIG5}, {"zhtw", CS_BIG5},
        {"traditional", CS_BIG5},
        {"ja", CS_SJIS}, {"jpn", CS_SJIS}, {"jp", CS_SJIS}, {"jap", CS_SJIS},
        {"japanese", CS_SJIS},
        {"ko", CS_EUCKR}, {"kor", CS_EUCKR}, {"korean", CS_EUCKR},
    };
    for (size_t i = 0; i < sizeof(map) / sizeof(map[0]); ++i)
        if (strcmp(map[i].token, t) == 0)
            return map[i].cs;
    return CS_NONE;
}

/* The last language token of the file name, "Movie.en.ru.srt" -> ru. */
static enum cs hint_from_path(const char *path) {
    if (!path)
        return CS_NONE;
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    enum cs found = CS_NONE;
    char tok[24];
    size_t n = 0;
    for (const char *p = base;; ++p) {
        int sep = *p == 0 || *p == '.' || *p == '_' || *p == '-' || *p == ' ' || *p == '[' ||
                  *p == ']' || *p == '(' || *p == ')';
        if (!sep) {
            if (n + 1 < sizeof(tok))
                tok[n++] = (char)tolower((unsigned char)*p);
            continue;
        }
        if (n) {
            tok[n] = 0;
            enum cs h = hint_from_token(tok);
            if (h != CS_NONE)
                found = h;
            n = 0;
        }
        if (*p == 0)
            break;
    }
    return found;
}

/* ---- Guessing from the bytes ------------------------------------------- */

struct dbcs_score {
    size_t pairs, bad;
    size_t trail_high, lead_high;
    size_t kana, hangul, simplified, traditional;
};

static const unsigned short simplified_marks[] = {0x8FD9, 0x4E2A, 0x4EEC, 0x4E3A, 0x8BF4, 0x4E48,
                                                  0x65F6, 0x6765, 0x53D1, 0x5BF9, 0x4F1A, 0x8FD8,
                                                  0x6CA1, 0x8FC7, 0x5173, 0x5F00, 0x4E1C, 0x4E66,
                                                  0x8F66, 0x8BDD, 0x4E3B, 0x95E8, 0x95EE, 0x8FDB};
static const unsigned short traditional_marks[] = {0x9019, 0x500B, 0x5011, 0x70BA, 0x8AAA, 0x9EBC,
                                                   0x6642, 0x4F86, 0x767C, 0x5C0D, 0x6703, 0x9084,
                                                   0x6C92, 0x904E, 0x95DC, 0x958B, 0x6771, 0x66F8,
                                                   0x8ECA, 0x8A71, 0x4E3B, 0x9580, 0x554F, 0x9032};

static int in_set(unsigned short v, const unsigned short *set, size_t n) {
    for (size_t i = 0; i < n; ++i)
        if (set[i] == v)
            return 1;
    return 0;
}

static void score_dbcs(enum cs cs, const unsigned char *p, size_t n, struct dbcs_score *s) {
    const struct dbcs *d = dbcs_of(cs);
    const int tw = d->trail_hi - d->trail_lo + 1;
    memset(s, 0, sizeof(*s));
    for (size_t i = 0; i < n;) {
        unsigned char b = p[i];
        if (b < 0x80) {
            ++i;
            continue;
        }
        if (cs == CS_SJIS && b >= 0xA1 && b <= 0xDF) {
            s->pairs++; /* half-width kana: readable, but not evidence of Japanese */
            ++i;
            continue;
        }
        if (b >= d->lead_lo && b <= d->lead_hi && i + 1 < n && p[i + 1] >= d->trail_lo &&
            p[i + 1] <= d->trail_hi) {
            unsigned short v = d->table[(b - d->lead_lo) * tw + (p[i + 1] - d->trail_lo)];
            if (v) {
                s->pairs++;
                if (p[i + 1] >= 0xA1)
                    s->trail_high++;
                if (b >= 0xA1)
                    s->lead_high++;
                if (v >= 0x3040 && v <= 0x30FF)
                    s->kana++;
                if (v >= 0xAC00 && v <= 0xD7A3)
                    s->hangul++;
                if (in_set(v, simplified_marks, sizeof(simplified_marks) / 2))
                    s->simplified++;
                if (in_set(v, traditional_marks, sizeof(traditional_marks) / 2))
                    s->traditional++;
                i += 2;
                continue;
            }
        }
        s->bad++;
        ++i;
    }
}

/* Whether the bytes are a convincing run of two-byte text in `cs`. */
static int dbcs_fits(enum cs cs, const struct dbcs_score *s) {
    if (s->pairs < 6)
        return 0;
    if (s->bad * 10 > s->pairs) /* more than ~9% unreadable */
        return 0;
    if (cs == CS_SJIS)
        return 1; /* kana and kanji lead bytes are all over the range */
    /* Accented Latin read as pairs has an ASCII-letter second byte. */
    return s->trail_high * 10 >= s->pairs * 6;
}

static enum cs guess_dbcs(const unsigned char *p, size_t n) {
    struct dbcs_score sc[4];
    int fits[4];
    int any = 0;
    for (int i = 0; i < 4; ++i) {
        score_dbcs((enum cs)(CS_GBK + i), p, n, &sc[i]);
        fits[i] = dbcs_fits((enum cs)(CS_GBK + i), &sc[i]);
        any |= fits[i];
    }
    if (!any)
        return CS_NONE;
    /* Kana is Japanese; hangul is Korean; then simplified vs traditional marks. */
    if (fits[2] && sc[2].kana * 5 >= sc[2].pairs)
        return CS_SJIS;
    /* Shift-JIS bytes also decode as hangul through cp949's extension: real
     * EUC-KR has both bytes at 0xA1 or above. */
    if (fits[3] && sc[3].hangul * 2 >= sc[3].pairs && sc[3].lead_high * 10 >= sc[3].pairs * 9)
        return CS_EUCKR;
    if (fits[0] && fits[1]) {
        if (sc[1].traditional > sc[0].simplified && sc[1].traditional > sc[1].simplified)
            return CS_BIG5;
        if (sc[0].simplified > 0 || sc[0].bad <= sc[1].bad)
            return CS_GBK;
        return CS_BIG5;
    }
    if (fits[0])
        return CS_GBK;
    if (fits[1])
        return CS_BIG5;
    if (fits[3])
        return CS_EUCKR;
    return CS_SJIS;
}

/* The most common letters of each script's single-byte code page. */
static int profile_score(const unsigned long *hist, const unsigned char *bytes, int count) {
    unsigned long sum = 0;
    for (int i = 0; i < count; ++i)
        sum += hist[bytes[i]];
    return (int)sum;
}

static enum cs guess_single(const unsigned char *p, size_t n) {
    unsigned long hist[256];
    memset(hist, 0, sizeof(hist));
    for (size_t i = 0; i < n; ++i)
        hist[p[i]]++;
    unsigned long high = 0, letters = 0;
    for (int b = 0x80; b < 256; ++b)
        high += hist[b];
    for (int b = 'A'; b <= 'Z'; ++b)
        letters += hist[b] + hist[b + 32];
    if (high == 0)
        return CS_1252;
    /* Accented Latin sits among ASCII letters; another script's text does not. */
    if (high * 4 < high + letters)
        return CS_1252;
    static const unsigned char ru[] = {0xE0, 0xE8, 0xEE, 0xF2, 0xF1, 0xF0, 0xE5, 0xED, 0xEA, 0xEB};
    static const unsigned char el[] = {0xE1, 0xE9, 0xEF, 0xF4, 0xF3, 0xF2, 0xE5, 0xED, 0xF1, 0xEA};
    static const unsigned char he[] = {0xE9, 0xE5, 0xE4, 0xEC, 0xF8, 0xE0, 0xEA, 0xF2, 0xFA, 0xF9};
    static const unsigned char ar[] = {0xC7, 0xE1, 0xE3, 0xE4, 0xE6, 0xED, 0xCA, 0xD1, 0xC8, 0xDF};
    static const unsigned char th[] = {0xD2, 0xC3, 0xE0, 0xB9, 0xA7, 0xC2, 0xCD, 0xD1, 0xCA, 0xB5};
    int s_ru = profile_score(hist, ru, 10) + (int)(hist[0xC0] / 4);
    int s_el = profile_score(hist, el, 10);
    int s_he = profile_score(hist, he, 10);
    int s_ar = profile_score(hist, ar, 10);
    int s_th = profile_score(hist, th, 10);
    /* Hebrew uses only E0-FA, so bytes above that count against it. */
    unsigned long above = 0;
    for (int b = 0xFB; b < 256; ++b)
        above += hist[b];
    if (above * 20 > high)
        s_he = 0;
    /* Windows-1251 has 0xC0-0xDF capitals and 0xE0-0xFF; Thai tops out at 0xFB. */
    int best = s_ru;
    enum cs cs = CS_1251;
    if (s_el > best) { best = s_el; cs = CS_1253; }
    if (s_he > best) { best = s_he; cs = CS_1255; }
    if (s_ar > best) { best = s_ar; cs = CS_1256; }
    if (s_th > best) { best = s_th; cs = CS_874; }
    return cs;
}

/* ---- Conversion --------------------------------------------------------- */

static char *convert_single(const unsigned char *p, size_t n, enum cs cs) {
    const unsigned short *t = single_tables[cs - CS_1250];
    char *out = (char *)malloc(n * 3 + 1);
    if (!out)
        return NULL;
    size_t w = 0;
    for (size_t i = 0; i < n; ++i) {
        unsigned char b = p[i];
        if (b < 0x80)
            out[w++] = (char)b;
        else
            w += put_utf8(out + w, t[b - 0x80]);
    }
    out[w] = 0;
    return out;
}

static char *convert_dbcs(const unsigned char *p, size_t n, enum cs cs) {
    const struct dbcs *d = dbcs_of(cs);
    const int tw = d->trail_hi - d->trail_lo + 1;
    char *out = (char *)malloc(n * 3 + 1);
    if (!out)
        return NULL;
    size_t w = 0;
    for (size_t i = 0; i < n;) {
        unsigned char b = p[i];
        if (b < 0x80) {
            out[w++] = (char)b;
            ++i;
            continue;
        }
        if (cs == CS_SJIS && b >= 0xA1 && b <= 0xDF) {
            w += put_utf8(out + w, 0xFF61u + (b - 0xA1u));
            ++i;
            continue;
        }
        if (b >= d->lead_lo && b <= d->lead_hi && i + 1 < n && p[i + 1] >= d->trail_lo &&
            p[i + 1] <= d->trail_hi) {
            unsigned short v = d->table[(b - d->lead_lo) * tw + (p[i + 1] - d->trail_lo)];
            if (v) {
                w += put_utf8(out + w, v);
                i += 2;
                continue;
            }
        }
        w += put_utf8(out + w, 0xFFFD);
        ++i;
    }
    out[w] = 0;
    return out;
}

static char *convert_utf16(const unsigned char *p, size_t n, int big) {
    char *out = (char *)malloc(n * 2 + 1);
    if (!out)
        return NULL;
    size_t w = 0;
    for (size_t i = 0; i + 1 < n; i += 2) {
        unsigned long u = big ? (unsigned long)((p[i] << 8) | p[i + 1])
                              : (unsigned long)((p[i + 1] << 8) | p[i]);
        if (u >= 0xD800 && u <= 0xDBFF && i + 3 < n) {
            unsigned long lo = big ? (unsigned long)((p[i + 2] << 8) | p[i + 3])
                                   : (unsigned long)((p[i + 3] << 8) | p[i + 2]);
            if (lo >= 0xDC00 && lo <= 0xDFFF) {
                u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00);
                i += 2;
            }
        }
        w += put_utf8(out + w, u);
    }
    out[w] = 0;
    return out;
}

static char *copy_bytes(const unsigned char *p, size_t n) {
    char *out = (char *)malloc(n + 1);
    if (!out)
        return NULL;
    memcpy(out, p, n);
    out[n] = 0;
    return out;
}

char *evo_charset_to_utf8(const unsigned char *data, size_t len, const char *path,
                          const char **out_name) {
    enum cs cs = CS_NONE;
    if (len >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF) {
        data += 3;
        len -= 3;
        cs = CS_UTF8;
    } else if (len >= 2 && data[0] == 0xFF && data[1] == 0xFE) {
        data += 2;
        len -= 2;
        cs = CS_UTF16LE;
    } else if (len >= 2 && data[0] == 0xFE && data[1] == 0xFF) {
        data += 2;
        len -= 2;
        cs = CS_UTF16BE;
    } else if (len >= 8) {
        /* UTF-16 with no BOM: ASCII text has a zero in every other byte. */
        size_t even = 0, odd = 0, probe = len < 512 ? len : 512;
        const size_t pairs = probe / 2;
        for (size_t i = 0; i + 1 < probe; i += 2) {
            even += data[i] == 0;
            odd += data[i + 1] == 0;
        }
        if (odd * 2 > pairs && even == 0)
            cs = CS_UTF16LE;
        else if (even * 2 > pairs && odd == 0)
            cs = CS_UTF16BE;
    }
    if (cs == CS_NONE && valid_utf8(data, len))
        cs = CS_UTF8;
    if (cs == CS_NONE) {
        cs = hint_from_path(path);
        if (is_dbcs(cs)) {
            struct dbcs_score sc;
            score_dbcs(cs, data, len, &sc);
            if (sc.pairs < 6 || sc.bad * 10 > sc.pairs * 3)
                cs = CS_NONE; /* the name lied */
        }
        if (cs == CS_NONE) {
            cs = guess_dbcs(data, len);
            if (cs == CS_NONE)
                cs = guess_single(data, len);
        }
    }
    if (out_name)
        *out_name = cs_names[cs];
    switch (cs) {
    case CS_UTF8:
        return copy_bytes(data, len);
    case CS_UTF16LE:
        return convert_utf16(data, len, 0);
    case CS_UTF16BE:
        return convert_utf16(data, len, 1);
    default:
        return is_dbcs(cs) ? convert_dbcs(data, len, cs) : convert_single(data, len, cs);
    }
}
